// Deterministic build script for dsh-plugin-whale.
// 1. Runs tsc (or Node's Module.stripTypeScriptTypes fallback) to emit lib/**/*.js
// 2. Bundles client modules in deterministic dependency order into lib/client.js
// 3. Validates syntax & window.__ModuleLoader__ registration in a VM sandbox.

import fs from 'node:fs'
import path from 'node:path'
import vm from 'node:vm'
import { fileURLToPath } from 'node:url'
import { execFileSync, spawnSync } from 'node:child_process'
import Module from 'node:module'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, '..')
const SRC_DIR = path.join(ROOT, 'src')
const LIB_DIR = path.join(ROOT, 'lib')

function findExecutable(binName) {
  const candidates = [
    process.env.TSC,
    path.join(ROOT, 'node_modules', '.bin', binName),
    path.join(ROOT, '..', 'node_modules', '.bin', binName)
  ].filter(Boolean)
  for (const c of candidates) {
    if (fs.existsSync(c)) return c
  }
  const whichRes = spawnSync('which', [binName], { encoding: 'utf-8' })
  if (whichRes.status === 0 && whichRes.stdout.trim()) {
    return whichRes.stdout.trim()
  }
  return null
}

function transformTsToJsFallback(tsSource) {
  let code = tsSource.replace(
    /constructor\s*\(\s*public\s+([a-zA-Z0-9_$]+)\s*:\s*[^,)=]+(\s*=\s*[^,)]+)?\s*,\s*public\s+([a-zA-Z0-9_$]+)\s*:\s*[^,)=]+(\s*=\s*[^,)]+)?\s*\)\s*\{/g,
    (_m, p1, d1, p2, d2) => {
      return `constructor(${p1}${d1 || ''}, ${p2}${d2 || ''}) {\n    this.${p1} = ${p1};\n    this.${p2} = ${p2};`
    }
  )
  code = code.replace(
    /constructor\s*\(\s*public\s+([a-zA-Z0-9_$]+)\s*:\s*[^,)=]+(\s*=\s*[^,)]+)?\s*,\s*public\s+([a-zA-Z0-9_$]+)\s*\?\s*:\s*[^,)=]+\s*\)\s*\{/g,
    (_m, p1, d1, p2) => {
      return `constructor(${p1}${d1 || ''}, ${p2}) {\n    this.${p1} = ${p1};\n    this.${p2} = ${p2};`
    }
  )

  if (typeof Module.stripTypeScriptTypes === 'function') {
    return Module.stripTypeScriptTypes(code)
  }
  throw new Error('Neither tsc nor Node.js Module.stripTypeScriptTypes is available.')
}

function getAllTsFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      files.push(...getAllTsFiles(full))
    } else if (entry.isFile() && entry.name.endsWith('.ts') && !entry.name.endsWith('.d.ts')) {
      files.push(full)
    }
  }
  return files
}

function buildEsmTree() {
  const tscBin = findExecutable('tsc')
  if (tscBin) {
    execFileSync(tscBin, ['-p', path.join(ROOT, 'tsconfig.json')], { stdio: 'inherit' })
    return
  }

  const tsFiles = getAllTsFiles(SRC_DIR)
  for (const srcFile of tsFiles) {
    const rel = path.relative(SRC_DIR, srcFile)
    const outFile = path.join(LIB_DIR, rel.replace(/\.ts$/, '.js'))
    const outDir = path.dirname(outFile)
    if (!fs.existsSync(outDir)) {
      fs.mkdirSync(outDir, { recursive: true })
    }
    const rawTs = fs.readFileSync(srcFile, 'utf-8')
    const js = transformTsToJsFallback(rawTs)
    fs.writeFileSync(outFile, js, 'utf-8')
  }
}

function stripImportsAndExportsForBundle(jsCode) {
  return jsCode
    .replace(/^\s*import\s+[\s\S]*?from\s+['"][^'"]+['"]\s*;?\s*$/gm, '')
    .replace(/^\s*import\s+['"][^'"]+['"]\s*;?\s*$/gm, '')
    .replace(/^\s*export\s+\*\s+from\s+['"][^'"]+['"]\s*;?\s*$/gm, '')
    .replace(/^\s*export\s+default\s+/gm, '')
    .replace(/^\s*export\s+(const|let|var|function|class)\s+/gm, '$1 ')
    .replace(/^\s*export\s*\{[^}]*\}\s*;?\s*$/gm, '')
    .replace(/\/\/# sourceMappingURL=.*$/gm, '')
    .trim()
}

function buildClientBundle() {
  const orderedLibModules = [
    path.join(LIB_DIR, 'format.js'),
    path.join(LIB_DIR, 'client/sound-player.js'),
    path.join(LIB_DIR, 'client/speech-synthesizer.js'),
    path.join(LIB_DIR, 'client/whale-stage-3d.js'),
    path.join(LIB_DIR, 'client/widget-ui.js'),
    path.join(LIB_DIR, 'client/bundle.js')
  ]

  const chunks = [
    '// DSH Whale Client Bundle (Auto-generated by scripts/build.mjs — DO NOT EDIT MANUALLY)',
    '(function () {'
  ]

  for (const modPath of orderedLibModules) {
    const relName = path.relative(ROOT, modPath)
    const jsContent = fs.readFileSync(modPath, 'utf-8')
    const cleaned = stripImportsAndExportsForBundle(jsContent)
    chunks.push(`\n  // --- Module: ${relName} ---`)
    chunks.push(cleaned)
  }

  chunks.push('})();\n')

  const bundleCode = chunks.join('\n')
  const outClientPath = path.join(LIB_DIR, 'client.js')
  fs.writeFileSync(outClientPath, bundleCode, 'utf-8')

  const dtsPath = path.join(LIB_DIR, 'client.d.ts')
  fs.writeFileSync(
    dtsPath,
    'export declare const name = "whale-client";\nexport declare const inject: string[];\nexport declare function apply(ctx: any): void;\n',
    'utf-8'
  )
}

function verifyOutputs() {
  const checkFiles = [
    path.join(LIB_DIR, 'index.js'),
    path.join(LIB_DIR, 'config.js'),
    path.join(LIB_DIR, 'services/merit-storage.js'),
    path.join(LIB_DIR, 'services/llm-speech-service.js'),
    path.join(LIB_DIR, 'services/whale-service.js'),
    path.join(LIB_DIR, 'tools/index.js'),
    path.join(LIB_DIR, 'client/whale-stage-3d.js'),
    path.join(LIB_DIR, 'client/bundle.js'),
    path.join(LIB_DIR, 'client.js')
  ]
  for (const f of checkFiles) {
    execFileSync(process.execPath, ['--check', f], { stdio: 'inherit' })
  }

  const clientCode = fs.readFileSync(path.join(LIB_DIR, 'client.js'), 'utf-8')
  let registered = null
  const sandbox = {
    window: {
      __ModuleLoader__: {
        load(entry) {
          registered = entry
        }
      }
    },
    document: undefined,
    console
  }
  vm.runInNewContext(clientCode, sandbox)
  if (!registered || registered.id !== 'dsh-plugin-whale' || typeof registered.factory !== 'function') {
    throw new Error('lib/client.js failed window.__ModuleLoader__ registration check!')
  }
}

buildEsmTree()
buildClientBundle()
verifyOutputs()
console.log('[build] Successfully built dsh-plugin-whale lib/**/*.js and lib/client.js')
